        // If this == registry.getNativeType(...), it calls super.toDebugHashCodeString()
        FunctionType ft = new FunctionType(registry, null, null, null) {
            @Override
            public String toDebugHashCodeString() {
                // Simulating the 'this == registry.getNativeType' logic
                if (this == nativeFuncType) {
                    return "super_hash_code";
                }
                return super.toDebugHashCodeString();
            }
        };
