        // Scenario: hasKnownTypeOfThis = true, paramNum = 2
        JSType typeOfThisKnown = mock(JSType.class);
        when(typeOfThisKnown.isUnknownType()).thenReturn(false);
        when(typeOfThisKnown.getDebugHashCodeString()).thenReturn("TypeThis");

        Call callWithParams = mock(Call.class);
        Node paramsNode = mock(Node.class);
        Node p1 = mock(Node.class);
        Node p2 = mock(Node.class);
        JSType p1Type = mock(JSType.class);
        JSType p2Type = mock(JSType.class);

        when(paramsNode.getChildCount()).thenReturn(2);
        when(paramsNode.getFirstChild()).thenReturn(p1);
        when(p1.getJSType()).thenReturn(p1Type);
        when(p1.getNext()).thenReturn(p2);
        when(p2.getJSType()).thenReturn(p2Type);
        when(p2.getNext()).thenReturn(null);

        when(p1Type.getDebugHashCodeString()).thenReturn("TypeP1");
        when(p2Type.getDebugHashCodeString()).thenReturn("TypeP2");

        JSType retType = mock(JSType.class);
        when(retType.getDebugHashCodeString()).thenReturn("TypeRet");
        when(callWithParams.returnType).thenReturn(retType);
